        insertFact.run(
          f.uuid,
          f.type,
          f.project,
          f.content,
          f.metadata,
          f.observedAt,
          f.supersededAt,
          f.supersededBy
        );
      }
    }

    return {
      sessions: data.sessions.length,
      messages: data.messages.length,
      toolUses: data.toolUses.length,
      entities: data.entities.length,
      links: data.links.length,
      facts: data.facts ? data.facts.length : 0,
    };
  });

